plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}
CFBundleIdentifier
com.wails.{{safeBundleID .Name}}
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
10.13.0

NSDownloadsFolderUsageDescription
Para poder listar y transferir archivos de tu carpeta Descargas desde el explorador SFTP.
NSDesktopFolderUsageDescription
Para poder listar y transferir archivos de tu Escritorio desde el explorador SFTP.
NSDocumentsFolderUsageDescription
Para poder listar y transferir archivos de tu carpeta Documentos desde el explorador SFTP.
NSRemovableVolumesUsageDescription
Para poder listar y transferir archivos de discos externos y pendrives desde el explorador SFTP.
NSNetworkVolumesUsageDescription
Para poder listar y transferir archivos de unidades de red montadas desde el explorador SFTP.
NSFileProviderDomainUsageDescription
Para poder listar y transferir archivos sincronizados por iCloud u otros proveedores desde el explorador SFTP.
NSHighResolutionCapable
true
NSHumanReadableCopyright
{{.Info.Copyright}}
{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions

      {{.Ext}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        com.wails.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
